True def transform(grid):
    out = [row[:] for row in grid]
    zero_cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 0]
    top = min(r for r, _ in zero_cells)
    left = min(c for _, c in zero_cells)
    rows = {top, top + 1}
    cols = {left, left + 1}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r in rows or c in cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
